import Foundation
import XCTest
@testable import iGenticApp

final class AgentLoopReadOnlyReceiptParityTests: XCTestCase {
    // The HMAC and exact wire JSON were generated by the existing
    // Node signReadOnlyDeviceKeyReceipt implementation; no iPhone was involved.
    private let nodeWire = """
    {"body":{"schema":1,"kind":"read-only-device-key-ack","requestId":"11111111-2222-4333-8444-555555555555","capability":"igentic.own_app.status.read","nonce":"22222222-3333-4444-8555-666666666666","observedAt":2000000010,"status":"key-holder-reports-read"},"signature":"5fab62c61d742fbf674ac743bbcce402f9c926bc125e0e39ff0ac60b8cf4e491"}
    """

    #if DEBUG && canImport(CryptoKit)
    private var key: Data { Data((0..<32).map(UInt8.init)) }
    private let id = "11111111-2222-4333-8444-555555555555"
    private let nonce = "22222222-3333-4444-8555-666666666666"
    private func fixture(
        key: Data? = nil,
        requestID: String? = nil,
        nonce: String? = nil,
        observedAt: Int = 2_000_000_010
    ) -> Data? {
        AgentLoopReadOnlyReceiptFixture.makeTestOnlyProof(
            secret: key ?? self.key,
            requestID: requestID ?? id,
            receiptNonce: nonce ?? self.nonce,
            observedAt: observedAt
        )
    }

    func testExactSwiftReceiptMatchesIndependentNodeTestVector() {
        XCTAssertEqual(String(data: try XCTUnwrap(fixture()), encoding: .utf8), nodeWire)
        // This is only key proof: never an iOS-execution or owner approval.
        XCTAssertFalse(nodeWire.contains("actionExecuted"))
        XCTAssertFalse(nodeWire.contains("ownerApproved"))
        XCTAssertFalse(nodeWire.contains("iPhoneConnected"))
    }

    func testReceiptChangesWithRequestNonceTimeAndKey() throws {
        let original = try XCTUnwrap(fixture())
        for variant in [
            fixture(key: Data((1...32).map(UInt8.init))),
            fixture(requestID: "99999999-2222-4333-8444-555555555555"),
            fixture(nonce: "99999999-3333-4444-8555-666666666666"),
            fixture(observedAt: 2_000_000_011),
        ] {
            XCTAssertNotEqual(try XCTUnwrap(variant), original)
        }
    }

    func testInvalidKeyTimeAndIdentifiersAreRejectedBeforeSigning() {
        XCTAssertNil(fixture(key: Data(repeating: 0, count: 32)))
        XCTAssertNil(fixture(key: Data(repeating: 1, count: 31)))
        XCTAssertNil(fixture(key: Data(repeating: 1, count: 32)))
        XCTAssertNil(fixture(requestID: "reminder.create"))
        XCTAssertNil(fixture(requestID: "ab111111-2222-4333-8444-555555555555".uppercased()))
        XCTAssertNil(fixture(nonce: "invalid"))
        XCTAssertNil(fixture(nonce: "bc222222-3333-4444-8555-666666666666".uppercased()))
        XCTAssertNil(fixture(observedAt: -1))
        XCTAssertNil(fixture(observedAt: 9_007_199_254_740_992))
    }

    func testFixtureCannotEncodeActionsOrPrivateModelText() throws {
        let bytes = try XCTUnwrap(fixture())
        let obj = try XCTUnwrap(
            JSONSerialization.jsonObject(with: bytes) as? [String: Any]
        )
        XCTAssertEqual(Set(obj.keys), ["body", "signature"])
        let body = try XCTUnwrap(obj["body"] as? [String: Any])
        XCTAssertEqual(Set(body.keys), [
            "schema", "kind", "requestId", "capability", "nonce",
            "observedAt", "status"
        ])
        XCTAssertEqual(body["capability"] as? String, "igentic.own_app.status.read")
        XCTAssertEqual(body["status"] as? String, "key-holder-reports-read")
    }
    #else
    func testUnsignedFixtureUnavailableOutsideDebugCryptoKit() {
        XCTAssertTrue(true) // Fixture is excluded at compile time.
    }
    #endif
}
